parameters.text:
=Classify this email:

From: {{ $json.email_sender }}
Subject: {{ $json.email_subject }}
Body: {{ $json.email_body }}

Return JSON with: category (action-required|FYI|meeting-request|newsletter|urgent), priority_score (1-10), summary (2 lines), action_needed (string), has_meeting_request (boolean), meeting_details (string).

parameters.jsCode:
const items = $input.all();
return items.map(item => {
  let parsed = {};
  try {
    const raw = item.json.output || '{}';
    parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch(e) {
    parsed = { category: 'FYI', priority_score: 3, summary: 'Parse error', action_needed: '', has_meeting_request: false, meeting_details: '' };
  }
  return {
    json: {
      email_sender: item.json.email_sender ?? '',
      email_subject: item.json.email_subject ?? '',
      email_body: item.json.email_body ?? '',
      email_date: item.json.email_date ?? '',
      email_id: item.json.email_id ?? '',
      thread_id: item.json.thread_id ?? '',
      category: parsed.category || 'FYI',
      priority_score: parsed.priority_score || 3,
      summary: parsed.summary || '',
      action_needed: parsed.action_needed || '',
      has_meeting_request: parsed.has_meeting_request || false,
      meeting_details: parsed.meeting_details || ''
    }
  };
});

