parameters.jsCode:
const allItems = $input.all();
const calItems  = allItems.filter(i => i.json.summary && i.json.start);
const taskItems = allItems.filter(i => i.json.email_subject && i.json.status === 'pending');

const meetings = calItems.length
  ? calItems.map(i => '  • ' + i.json.summary + ' at ' + (i.json.start?.dateTime || i.json.start?.date || 'TBD')).join('\n')
  : '  No meetings scheduled today';

const tasks = taskItems.length
  ? taskItems.sort((a,b) => Number(b.json.priority_score||0) - Number(a.json.priority_score||0))
      .slice(0, 5)
      .map(i => '  • [P' + (i.json.priority_score||0) + '] ' + i.json.email_subject).join('\n')
  : '  No pending tasks';

const today = new Date().toDateString();
const brief = 'Good morning!\n\nYour Executive Brief for ' + today + '\n\n' +
  '📅 TODAY\'S MEETINGS (' + calItems.length + '):\n' + meetings + '\n\n' +
  '⚡ TOP PRIORITY TASKS (' + taskItems.length + ' pending):\n' + tasks + '\n\n' +
  'Have a productive day!';

return [{ json: {
  brief,
  subject: 'Morning Brief — ' + today,
  meetings_count: calItems.length,
  tasks_count: taskItems.length
}}];

const items = $input.all();
const today = new Date().toDateString();
const todayItems = items.filter(i => {
  const ts = i.json.timestamp;
  return ts && new Date(ts).toDateString() === today;
});

const done    = todayItems.filter(i => i.json.status === 'done').length;
const pending = todayItems.filter(i => i.json.status === 'pending').length;
const urgent  = todayItems.filter(i => i.json.category === 'urgent').length;
const meetings= todayItems.filter(i => i.json.category === 'meeting-request').length;
const tasks   = todayItems.filter(i => i.json.action_taken && i.json.action_taken.includes('task')).length;

const completedList = todayItems.filter(i=>i.json.status==='done')
  .map(i => '  • ' + i.json.email_subject).join('\n') || '  None';
const pendingList = todayItems.filter(i=>i.json.status==='pending')
  .map(i => '  • [P' + (i.json.priority_score||0) + '] ' + i.json.email_subject).join('\n') || '  None';

const summary =
  'EOD Executive Summary — ' + today + '\n\n' +
  '📊 TODAY\'S ACTIVITY STATS\n' +
  '  • Total emails processed: ' + todayItems.length + '\n' +
  '  • Urgent items handled: ' + urgent + '\n' +
  '  • Tasks created in Asana: ' + tasks + '\n' +
  '  • Meetings scheduled: ' + meetings + '\n' +
  '  • Completed: ' + done + '  |  Pending: ' + pending + '\n\n' +
  '✅ COMPLETED TODAY\n' + completedList + '\n\n' +
  '⏳ PENDING FOR TOMORROW\n' + pendingList + '\n\nGreat work today!';

return [{ json: { summary, subject: 'EOD Summary — ' + today, total: todayItems.length } }];

const items = $input.all();
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const weekItems = items.filter(i => {
  const ts = i.json.timestamp;
  return ts && new Date(ts) >= weekAgo;
});

const byCategory = {};
weekItems.forEach(i => {
  const cat = i.json.category || 'other';
  byCategory[cat] = (byCategory[cat] || 0) + 1;
});

const totalEmails     = weekItems.length;
const tasksCreated    = weekItems.filter(i => (i.json.action_taken||'').includes('task')).length;
const meetingsSched   = weekItems.filter(i => i.json.category === 'meeting-request').length;
const urgentHandled   = weekItems.filter(i => i.json.category === 'urgent').length;
const done            = weekItems.filter(i => i.json.status === 'done').length;
const completionRate  = totalEmails > 0 ? Math.round((done / totalEmails) * 100) : 0;

const catBreakdown = Object.entries(byCategory)
  .map(([k,v]) => '    • ' + k + ': ' + v + ' emails').join('\n') || '    • No data';

const report =
  '═══════════════════════════════════════\n' +
  '  WEEKLY EXECUTIVE OPERATIONS REPORT\n' +
  '  Week of ' + weekAgo.toDateString() + ' – ' + now.toDateString() + '\n' +
  '═══════════════════════════════════════\n\n' +
  '📈 KEY METRICS\n' +
  '  • Total Emails Processed : ' + totalEmails + '\n' +
  '  • Asana Tasks Created    : ' + tasksCreated + '\n' +
  '  • Meetings Scheduled     : ' + meetingsSched + '\n' +
  '  • Urgent Items Handled   : ' + urgentHandled + '\n' +
  '  • Overall Completion Rate: ' + completionRate + '%\n\n' +
  '📊 EMAIL BREAKDOWN BY CATEGORY\n' + catBreakdown + '\n\n' +
  '═══════════════════════════════════════\n' +
  'Generated by Executive Business Operations Agent';

return [{ json: { report, subject: 'Weekly Ops Report — ' + now.toDateString(), total_emails: totalEmails, completion_rate: completionRate } }];

parameters.text:
=Analyze this reply email and determine the new status of the original task.

Original Subject: {{ $('Read Pending Rows').item.json.Email_subject }}
Original Summary: {{ $('Read Pending Rows').item.json.Summary }}

Reply From: {{ $json.from?.value?.[0]?.address ?? $json.from }}
Reply Text: {{ $json.text ?? $json.snippet ?? "" }}

Classify the reply intent:
- "approved" — sender confirms, approves, says yes, looks good, proceed, done, confirmed
- "escalated" — sender says urgent, escalate, critical, needs immediate attention, emergency
- "pending" — reply is unclear, asks a question, or does not change the task status

Return JSON with new_status and reason.

parameters.jsCode:
const items = $input.all();
return items.map(item => {
  let parsed = {};
  try {
    const raw = item.json.output || '{}';
    parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch(e) {
    parsed = { new_status: 'pending', reason: 'Parse error' };
  }
  const validStatuses = ['approved', 'escalated', 'pending'];
  const newStatus = validStatuses.includes(parsed.new_status) ? parsed.new_status : 'pending';
  return {
    json: {
      ...item.json,
      new_status: newStatus,
      reason: parsed.reason || '',
      Email_subject: item.json.Email_subject || '',
      Email_sender: item.json.Email_sender || '',
      Action_taken: item.json.Action_taken || ''
    }
  };
});

